				displayName = "$STR_A3_action_deploy_parachute";
				condition = "player in this";
				statement = "[this] spawn BIS_fnc_ejectionSeatRelease";
				position = "pilotcontrol";
				radius = 10;
				onlyforplayer = 1;
				showWindow = 0;
