```sqf
{
	private _verticalValue = _x; // needed, otherwise _horizontalValues' _x made this one inaccessible
	{
		[_x, _verticalValue] call TAG_fnc_doSomething;
	} forEach _horizontalValues;
} forEach _verticalValues;
